const lessons=[{"sentences":[{"speaker":"A","text":"Hello Mark, have you thought about our upcoming presentation on urban transport yet?","position":1,"audioStartSeconds":0,"audioEndSeconds":5.597791666666667},{"speaker":"B","text":"Hi Sarah, I looked at a few interesting topics although I found most of them too complicated.","position":2,"audioStartSeconds":5.797791666666667,"audioEndSeconds":11.896625},{"speaker":"A","text":"My initial suggestion was comparing bicycle sharing schemes in three major European capitals.","position":3,"audioStartSeconds":12.096625,"audioEndSeconds":18.282958333333333},{"speaker":"B","text":"That sounds brilliant because bicycles are very popular when discussing modern green cities.","position":4,"audioStartSeconds":18.482958333333332,"audioEndSeconds":24.295583333333333},{"speaker":"A","text":"However, gathering accurate financial data from three different cities might take longer than we expect.","position":5,"audioStartSeconds":24.495583333333332,"audioEndSeconds":31.157958333333333},{"speaker":"B","text":"You are completely right if we consider our strict deadline next week.","position":6,"audioStartSeconds":31.357958333333332,"audioEndSeconds":35.765166666666666},{"speaker":"A","text":"What if we focus exclusively on our local city transport network instead?","position":7,"audioStartSeconds":35.96516666666667,"audioEndSeconds":41.158458333333336},{"speaker":"B","text":"That would be much easier because we can easily interview local commuters.","position":8,"audioStartSeconds":41.35845833333333,"audioEndSeconds":46.0105},{"speaker":"A","text":"We should also include a short survey about recent bus punctuality improvements.","position":9,"audioStartSeconds":46.2105,"audioEndSeconds":51.532666666666664},{"speaker":"B","text":"Students love real statistics when they watch presentations in our seminar group.","position":10,"audioStartSeconds":51.73266666666667,"audioEndSeconds":57.067708333333336},{"speaker":"A","text":"Shall I prepare the introduction slides while you design the questionnaire?","position":11,"audioStartSeconds":57.26770833333333,"audioEndSeconds":61.68779166666667},{"speaker":"B","text":"That division of labour works perfectly for me today.","position":12,"audioStartSeconds":61.887791666666665,"audioEndSeconds":65.547625},{"speaker":"A","text":"Let us meet again on Thursday afternoon to practise our speaking parts together.","position":13,"audioStartSeconds":65.747625,"audioEndSeconds":70.86929166666667},{"speaker":"B","text":"I will bring the printed handouts then so we are fully prepared.","position":14,"audioStartSeconds":71.06929166666667,"audioEndSeconds":75.18391666666666}],"questions":[{"prompt":"What is the primary topic of the students' upcoming presentation?","options":["Rural farming methods.","Urban transport.","Global aviation history."],"answer":"B","evidenceSentence":1,"evidence":"our upcoming presentation on urban transport yet","explanation":"Speaker A explicitly mentions that their presentation is about urban transport."},{"prompt":"What was Sarah's initial idea for the project?","options":["Comparing bicycle sharing schemes.","Interviewing local taxi drivers.","Analyzing electric train engines."],"answer":"A","evidenceSentence":3,"evidence":"comparing bicycle sharing schemes in three major European capitals","explanation":"Sarah states that her first suggestion was comparing bicycle sharing schemes in three capitals."},{"prompt":"Why do they reject the initial idea about European capitals?","options":["They dislike riding bicycles.","Gathering financial data would take too long.","The professor banned European topics."],"answer":"B","evidenceSentence":5,"evidence":"gathering accurate financial data from three different cities might take longer","explanation":"They discard the European capitals idea because collecting financial data from three cities would take too much time before their deadline."},{"prompt":"What do they decide to focus on instead?","options":["International airports.","Their local city transport network.","National highway construction."],"answer":"B","evidenceSentence":7,"evidence":"focus exclusively on our local city transport network","explanation":"Speaker A suggests shifting the focus to their local city transport network, which they agree to do."},{"prompt":"What task will Mark take responsibility for?","options":["Designing the questionnaire.","Recording a video interview.","Writing the final essay."],"answer":"A","evidenceSentence":11,"evidence":"while you design the questionnaire","explanation":"Speaker A asks Mark to design the questionnaire after she prepares the introduction slides."},{"prompt":"When will the speakers meet next to practise?","options":["On Monday morning.","On Thursday afternoon.","On Friday evening."],"answer":"B","evidenceSentence":13,"evidence":"meet again on Thursday afternoon","explanation":"Speaker A suggests meeting on Thursday afternoon to rehearse their speaking parts."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
